/* @prim:begin 65-question-pair */
.qpair { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); background: var(--surface); border: 1px solid var(--border); border-radius: var(--ds-r-md); overflow: hidden; }
.qpair-head { margin: 0; padding: var(--sp-1, 8px) var(--sp-3, 24px); background: var(--surface-2); border-bottom: 1px solid var(--border); font-family: var(--ds-font-mono); font-size: var(--fs-label); font-weight: 700; letter-spacing: 0.14em; text-transform: uppercase; line-height: 1.6; color: var(--muted); }
.qpair-head.ask { color: var(--cyan); border-left: 1px solid var(--border); }
.qpair-row { display: contents; }
.qpair-row > div { padding: var(--sp-2, 16px) var(--sp-3, 24px); border-top: 1px solid var(--border); text-wrap: pretty; }
.qpair-head.ask + .qpair-row > div { border-top: 0; }
.qpair-said { color: var(--text-secondary); }
.qpair-ask { color: var(--text); border-left: 1px solid var(--border); }
@media (max-width: 640px) { .qpair { grid-template-columns: minmax(0, 1fr); } .qpair-head.ask { display: none; } .qpair-row > .qpair-ask { border-top: 0; border-left: 0; padding-top: 0; } .qpair-row > .qpair-ask::before { content: attr(data-lead) " "; font-weight: 600; color: var(--cyan); } }
@container (max-width: 40rem) { .qpair { grid-template-columns: minmax(0, 1fr); } .qpair-head.ask { display: none; } .qpair-row > .qpair-ask { border-top: 0; border-left: 0; padding-top: 0; } .qpair-row > .qpair-ask::before { content: attr(data-lead) " "; font-weight: 600; color: var(--cyan); } }
@media print { .qpair { column-gap: var(--sp-3, 24px); background: none; border-width: 0; border-radius: 0; break-inside: avoid; } .qpair-head { background: none; padding: 0 0 6px; border-bottom: 1.5px solid var(--text); } .qpair-head.ask { border-left: 0; border-bottom-color: var(--cyan); } .qpair-row > div { padding: 5px 0; break-inside: avoid; } .qpair-ask { border-left: 0; } }
/* @prim:end 65-question-pair */

