function kEsc(s){return String(s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];});}
function kSlot(i){return i===undefined?document.querySelector('[data-stage]'):document.querySelector('[data-state="'+i+'"]');}
var QP=[['Volume indicators can miss a rising signal; every day without a call costs time to market.','How often was your peaked-or-rising read right, and what would have flagged it wrong before the order?'],['A missed simulation means bad data or a wrong hypothesis.','For the last miss, which was it, and can your setup tell next time?']];
function kitQPair(host,n){var w=document.createElement('div');w.className='qpair';w.innerHTML='<h3 class="qpair-head">What you raised</h3><h3 class="qpair-head ask">Worth asking</h3>'+QP.slice(0,n).map(function(r){return '<div class="qpair-row"><div class="qpair-said">'+kEsc(r[0])+'</div><div class="qpair-ask" data-lead="Worth asking:">'+kEsc(r[1])+'</div></div>'}).join('');host.appendChild(w);return w}
